const fs = require('fs');

function main() {
  const data = fs.readFileSync(0, 'utf8').split(/\s+/).map(Number);
  let idx = 0;
  const T = data[idx++];
  const N = data[idx++];
  const xs = [];
  for (let i = 0; i < N; i++) xs.push(data[idx++]);
  xs.sort((a, b) => a - b);

  // neighborhoods (lengths doubled to keep integers)
  let min2 = Infinity;
  // first city: from 0 to (x0+x1)/2
  min2 = Math.min(min2, xs[0] + xs[1]);
  // middle cities: from (x_{i-1}+x_i)/2 to (x_i+x_{i+1})/2
  for (let i = 1; i < N - 1; i++) {
    min2 = Math.min(min2, xs[i + 1] - xs[i - 1]);
  }
  // last city: from (x_{n-2}+x_{n-1})/2 to T
  min2 = Math.min(min2, 2 * T - (xs[N - 2] + xs[N - 1]));

  const ans = min2 / 2;
  console.log(ans.toFixed(2));
}

main();
